use short_hhe_control::{coupled,record,durable,material,radiation::{self,Grid},Fallible,err};
use rei_microphysics::{igm_config::parse_config,audit_counts};
use std::{path::Path,fs};
const CONFIG:&str=include_str!("../../../long-flrw/configs/igm_manufactured_z12_to10.cfg");
macro_rules! image{($s:expr)=>{format!("{:?}\n{:?}\n{:?}\n{:?}\n{:?}\n{:?}\n{:?}\n{:?}\n{:?}\n{:?}\n",$s.s,$s.y,&$s.density,($s.active,$s.radiation),$s.material,($s.iterations,$s.norm),($s.n_ratio,$s.e_ratio),$s.accepted_trace,$s.trial_trace,record::AUTHORITY)}}
fn run()->Fallible<()>{let args:Vec<_>=std::env::args().collect();if args.len()!=4{return Err("mode root output required".into())}let mode=args[1].as_str();if !["legacy","off","live","prime","resume","probe","republish"].contains(&mode){return Err("UNKNOWN_RECORD_MODE".into())}let root=Path::new(&args[2]);let out=Path::new(&args[3]);fs::create_dir_all(out).map_err(err)?;let mut cfg=parse_config(CONFIG).map_err(err)?;
 if mode=="legacy"{let grid=short_hhe_baseline::radiation::Grid::new(&cfg,512,4)?;let mut state=short_hhe_baseline::coupled::State::new(&cfg,&grid)?;let p=cfg.background.at_ln_a(cfg.start).map_err(err)?;let initial=state.y[3]+short_hhe_baseline::material::binding(state.y,p.n_he_cm3/p.n_h_cm3);fs::write(out.join("startup.txt"),format!("{:?}\n",audit_counts::read())).map_err(err)?;for k in 1..=2{state=short_hhe_baseline::coupled::advance(&cfg,&grid,&state,short_hhe_baseline::radiation::time_at(&cfg,k,192),initial)?;fs::write(out.join(format!("step{k}.science.txt")),image!(state)).map_err(err)?;}fs::write(out.join("work.txt"),format!("{:?}\n",audit_counts::read())).map_err(err)?;println!("LEGACY_TWO_REAL_ACCEPTANCES {:?}",audit_counts::read());return Ok(())}
 let mut grid=Grid::new(&cfg,512,4)?;let initial_state=coupled::State::new(&cfg,&grid)?;let mut initial_y=initial_state.y;let p=cfg.background.at_ln_a(cfg.start).map_err(err)?;let initial=initial_y[3]+material::binding(initial_y,p.n_he_cm3/p.n_h_cm3);
 if let Ok(mutant)=std::env::var("REI_RECORD_CONTEXT_MUTANT"){match mutant.as_str(){"clock"=>cfg.start=f64::from_bits(cfg.start.to_bits()+1),"source"=>cfg.source.photons_per_h_per_s=f64::from_bits(cfg.source.photons_per_h_per_s.to_bits()+1),"grid"=>grid.nodes[0].1=f64::from_bits(grid.nodes[0].1.to_bits()+1),"gas"=>initial_y[0]=f64::from_bits(initial_y[0].to_bits()+1),_=>return Err("UNKNOWN_CONTEXT_MUTANT".into())}}
 let ctx=durable::Context::new(&cfg,&grid,initial_y);let startup=audit_counts::read();fs::write(out.join("startup.txt"),format!("{startup:?}\n")).map_err(err)?;record::set_enabled(mode!="off");let mut store=None;let mut state=initial_state;
 if ["resume","probe","republish"].contains(&mode){let(s,x)=durable::Store::resume(root,&ctx,&cfg,&grid,initial)?;store=Some(s);state=x;}else if mode!="off"{store=Some(durable::Store::create(root)?)}
 if mode=="republish"{let rejected=store.as_mut().unwrap().publish(&ctx,&cfg,&grid,&state,initial).is_err();if !rejected{return Err("REPUBLISH_NOT_REFUSED".into())}println!("REPUBLISH_REFUSED startup={startup:?} after={:?}",audit_counts::read());return Ok(())}
 if mode=="probe"{record::verify_state(&cfg,&grid,&state,initial_y)?;let mut w=record::W(Vec::new());record::write_state(&mut w,&state);fs::write(out.join("typed.bin"),w.0).map_err(err)?;fs::write(out.join("science.txt"),image!(state)).map_err(err)?;println!("PROBE_NO_SCIENCE startup={startup:?} after={:?}",audit_counts::read());return Ok(())}
 let first=state.accepted_records.len();if mode=="resume"&&first!=1{return Err("NO_EXTENSION_BEYOND_TWO_TRANSITIONS".into())}
 for k in first+1..=2{let candidate=coupled::advance(&cfg,&grid,&state,radiation::time_at(&cfg,k,192),initial)?;
  if let Some(store)=store.as_mut(){if !store.publish(&ctx,&cfg,&grid,&candidate,initial)?{eprintln!("PUBLISHED_DIRECTORY_DURABILITY_UNCERTAIN");std::process::exit(74)}}state=candidate;fs::write(out.join(format!("step{k}.science.txt")),image!(state)).map_err(err)?;fs::write(out.join("work.txt"),format!("{:?}\n",audit_counts::read())).map_err(err)?;
  if mode=="prime"{fs::write(out.join("READY"),b"actual accepted first transition durably published\n").map_err(err)?;println!("ACTUAL_FIRST_MIDPOINT_COMMITTED {:?}",audit_counts::read());loop{std::thread::sleep(std::time::Duration::from_millis(50))}}
 }
 if mode!="off"{record::verify_state(&cfg,&grid,&state,initial_y)?;let mut w=record::W(Vec::new());record::write_state(&mut w,&state);fs::write(out.join("typed.bin"),w.0).map_err(err)?;}
 println!("TWO_REAL_MIDPOINT_ACCEPTANCES mode={mode} RHS_SIGMA={:?} projected_full_wide=HOLD",audit_counts::read());Ok(())}
fn main(){if let Err(e)=run(){eprintln!("RECORD_REFUSAL {e}; COUNTS={:?}",audit_counts::read());std::process::exit(2)}}
